package ru.neverland.townyelections;
import java.util.*;
import java.math.BigDecimal;
/** Immutable candidate statements and measurable conditions. No prizes, debits or automatic sanctions. */
public final class ElectionPrograms {
    private ElectionPrograms(){}public enum Kind{BUILDING,POPULATION,POLLUTION}
    public record Evidence(boolean known,String value,long at,String issue){public Evidence{if(value==null||issue==null||issue.length()>240||at<0)throw new IllegalArgumentException("Неверные сведения");if(known){var n=new BigDecimal(value);if(n.signum()<0||n.compareTo(BigDecimal.valueOf(1_000_000))>0)throw new IllegalArgumentException("Сведения вне диапазона");}else if(!value.isEmpty())throw new IllegalArgumentException("Неизвестный показатель должен быть пустым");}public static Evidence unknown(String why,long now){return new Evidence(false,"",now,why);}public static Evidence known(long value,long now){return new Evidence(true,Long.toString(value),now,"");}}
    public record Promise(Kind kind,String project,long target,Evidence baseline){public Promise{Objects.requireNonNull(kind);Objects.requireNonNull(baseline);if(project==null||(kind==Kind.BUILDING?!project.matches("[a-z][a-z0-9_]{0,63}"):!project.isEmpty()))throw new IllegalArgumentException("Неверная цель программы");long max=kind==Kind.BUILDING?5:kind==Kind.POPULATION?1_000_000:100;long min=kind==Kind.POLLUTION?0:1;if(target<min||target>max)throw new IllegalArgumentException("Цель вне диапазона");}public String key(){return kind+":"+project;}public boolean met(Evidence evidence){return evidence.known()&&(kind==Kind.POLLUTION?new BigDecimal(evidence.value()).compareTo(BigDecimal.valueOf(target))<=0:new BigDecimal(evidence.value()).compareTo(BigDecimal.valueOf(target))>=0);}}
    public record Program(UUID campaign,UUID town,UUID candidate,String name,String race,String statement,List<Promise> promises,long revision,long submittedAt){public Program{Objects.requireNonNull(campaign);Objects.requireNonNull(town);Objects.requireNonNull(candidate);promises=List.copyOf(promises);if(name==null||name.isBlank()||name.length()>80||race==null||!race.matches("[a-z][a-z0-9_]{0,39}")||statement==null||statement.length()>400||promises.size()>3||revision<1||submittedAt<0)throw new IllegalArgumentException("Неверная программа");var keys=new HashSet<String>();for(var p:promises)if(!keys.add(p.key()))throw new IllegalArgumentException("Повтор цели");}public String key(){return campaign+"/"+candidate;}}
    public record Frozen(UUID campaign,UUID town,long at,boolean bound,Map<UUID,Program> programs){public Frozen{Objects.requireNonNull(campaign);Objects.requireNonNull(town);programs=Map.copyOf(programs);if(at<0||programs.size()>128)throw new IllegalArgumentException("Слишком много программ");for(var e:programs.entrySet())if(!e.getKey().equals(e.getValue().candidate())||!campaign.equals(e.getValue().campaign())||!town.equals(e.getValue().town()))throw new IllegalArgumentException("Программа другой кампании");}}
    public record State(Map<String,Program> drafts,Map<UUID,Frozen> frozen,long revision){public State{drafts=Map.copyOf(drafts);frozen=Map.copyOf(frozen);if(drafts.size()>10_000||frozen.size()>10_000||revision<0)throw new IllegalArgumentException("Реестр программ заполнен; требуется архивирование");var counts=new HashMap<UUID,Integer>();for(var e:drafts.entrySet()){if(!e.getKey().equals(e.getValue().key())||frozen.containsKey(e.getValue().campaign()))throw new IllegalArgumentException("Неверный черновик");if(counts.merge(e.getValue().campaign(),1,Integer::sum)>128)throw new IllegalArgumentException("Не более 128 программ на кампанию");}for(var e:frozen.entrySet())if(!e.getKey().equals(e.getValue().campaign()))throw new IllegalArgumentException("Неверное закрепление программы");}public static State empty(){return new State(Map.of(),Map.of(),0);}public State draft(Program value){if(frozen.containsKey(value.campaign()))throw new IllegalArgumentException("Программы уже закреплены для голосования");var next=new HashMap<>(drafts);var before=next.get(value.key());if(value.revision()!=(before==null?1:before.revision()+1))throw new IllegalArgumentException("Программа изменилась");next.put(value.key(),value);return new State(next,frozen,Math.incrementExact(revision));}public State bind(UUID campaign){var value=frozen.get(campaign);if(value==null||value.bound())return this;var next=new HashMap<>(frozen);next.put(campaign,new Frozen(value.campaign(),value.town(),value.at(),true,value.programs()));return new State(drafts,next,Math.incrementExact(revision));}public State freeze(UUID campaign,UUID town,Set<UUID> eligible,long now){if(frozen.containsKey(campaign))return this;var selected=new HashMap<UUID,Program>();var next=new HashMap<>(drafts);for(var p:drafts.values())if(p.campaign().equals(campaign)){if(!p.town().equals(town))throw new IllegalArgumentException("Чужая программа");if(eligible.contains(p.candidate()))selected.put(p.candidate(),p);next.remove(p.key());}var fixed=new HashMap<>(frozen);fixed.put(campaign,new Frozen(campaign,town,now,false,selected));return new State(next,fixed,Math.incrementExact(revision));}}
}
